import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Icon, Row, Col, Input, Alert, Table, Tooltip } from 'antd'
import swal from 'sweetalert2'
import Cookies from 'universal-cookie'
import QueryString from 'query-string'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import insuranceAction from '../../../../redux/policy/actions'
import gocarAction from '../../../redux/gocar/actions'
import QuerySearchBuilder from '../../../../helpers/querySearchBuilder'
import GocarTableStyled from './gocarTable.style'
import { tableColumns } from '../GocarComponents/tableData'

const cookies = new Cookies()

const { getGocarSimpleData } = gocarAction
const { sendReport } = insuranceAction

class GocarSimpleTable extends Component {
  constructor (props) {
    super(props)
    this.state = {
      searchText: '',
      searchTextQuery: {},
      limit: 10,
      offset: 0
    }
  }

  componentDidMount () {
    const querySearch = QueryString.parse(this.props.location.search)
    this.fetch(querySearch)
  }

  fetch = (params = {}) => {
    const { offset, limit, orderBy, startDate, endDate } = params
    const offsetNumber = Number(offset) || 0
    const limitNumber = Number(limit) || 10
    delete params.offset
    delete params.limit

    this.setState({
      searchText: '',
      orderIdentifier: orderBy,
      limit: limitNumber,
      offset: offsetNumber
    })
    this.props.getGocarSimpleData({
      ...params,
      orderBy,
      limit: limitNumber,
      offset: offsetNumber,
      startDate,
      endDate,
      policyState: '5,3'
    })
  }

  downloadExcel = () => {
    const { profileData } = this.props

    swal({
      title: 'Report will send to your email ',
      input: 'email',
      inputValue: profileData.email,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      preConfirm: mail => {
        this.props.sendReport({ email: mail, product_key: 'go-car-simple', policyState: 'CANCELLED,5' })
      },
      allowOutsideClick: () => false
    }).then(result => {
      if (result.dismiss !== 'cancel') {
        swal({ type: 'success', title: '', text: 'success' })
      }
    })
  }

  onClearFilter = () => {
    const { location } = this.props
    this.props.history.push({ pathname: location.pathname, search: '' })
    this.fetch()
  }

  onFilterChange (val) {
    cookies.set('querySearch', val.target.value, { path: '/' })
    this.setState({ searchInput: val.target.value })
    this.state.gridOptions.api.setQuickFilter(val.target.value)
  }

  onView = (id) => {
    this.props.history.push({ pathname: `/gocar/rejected/simple/${id}`, state: { params: { internalID: id } } })
  }

  handlePageChange = (val) => {
    const { location } = this.props
    const { current, pageSize } = val
    const searchText = {}
    searchText['offset'] = (current - 1) * pageSize
    searchText['limit'] = 10
    const search = QuerySearchBuilder(searchText)
    this.props.history.push({ pathname: location.pathname, search })
    this.fetch(searchText)
  }

  handleSearch = (selectedKeys, dataIndex) => {
    const { location, history } = this.props
    const params = new URLSearchParams(location)
    delete params['limit']
    delete params['offset']
    params[dataIndex] = selectedKeys
    const search = QuerySearchBuilder(params)
    history.push({ pathname: location.pathname, search })
    this.fetch(params)
  }

  getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    }
  })

  render () {
    const { gocarData, goCarDataLoading } = this.props
    const { metadata = {} } = gocarData

    const columns = [
      {
        title: 'Action',
        dataIndex: 'InternalID',
        key: 'action',
        render: (item) => <Icon type='eye' onClick={() => this.onView(item)} />
      },
      ...tableColumns(this)
    ]

    return (
      <GocarTableStyled>
        <LayoutContentWrapper className='simple-table'>
          {this.state.error && (
            <Row className='row-error'>
              <Col span={24}>
                <Alert className='error-alert' message='Ooops, something went terribly wrong!' type='error' closeText='Close' />
              </Col>
            </Row>
          )}
          <LayoutContent className='table-container'>
            <Row gutter={16}>
              <Col className='gutter-row-export-csv table-col' span={24}>
                <h3>Gocar Simple</h3>
                <div className='btn-container'>
                  <Button
                    className='btn-download'
                    onClick={this.onClearFilter}
                  >
                    <Icon type='cross' />Clear Filters
                  </Button>
                  <Tooltip
                    placement='topLeft'
                    title='This will email the excel of rejected gojek drivers'
                  >
                    <Button
                      className='btn-download'
                      onClick={this.downloadExcel}
                      style={{ marginRight: '10px' }}
                    ><Icon type='cloud' /> Download</Button>
                  </Tooltip>
                </div>
              </Col>
            </Row>
            <Row>
              <Table
                dataSource={gocarData.goCarList}
                columns={columns}
                className='table'
                bordered
                pagination={{
                  pageSize: 10,
                  total: Number(metadata.total_records),
                  current: (metadata.offset / metadata.limit) + 1
                }}
                onChange={this.handlePageChange}
                loading={!!goCarDataLoading}
              />
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      </GocarTableStyled>
    )
  }
}

export default connect(
  state => ({
    gocarData: state.Gocar,
    dataProfile: state.Auth.profile,
    goCarDataLoading: state.Loading.GET_GOCAR_SIMPLE_DATA,
    profileData: state.Auth.profile
  }),
  {
    getGocarSimpleData,
    sendReport
  }
)(GocarSimpleTable)
